import{_ as i,o as e,c as a,ah as s}from"./chunks/framework.CPHJ30oF.js";const p=JSON.parse('{"title":"19-Docker安全全景扫描-Rootless模式与镜像漏洞检测实战","description":"","frontmatter":{},"headers":[{"level":2,"title":"引言","slug":"引言","link":"#引言","children":[]},{"level":2,"title":"1. 容器并非天然安全","slug":"_1-容器并非天然安全","link":"#_1-容器并非天然安全","children":[]},{"level":2,"title":"2. Rootless 模式：降低特权风险","slug":"_2-rootless-模式-降低特权风险","link":"#_2-rootless-模式-降低特权风险","children":[]},{"level":2,"title":"3. 镜像漏洞扫描","slug":"_3-镜像漏洞扫描","link":"#_3-镜像漏洞扫描","children":[]},{"level":2,"title":"4. 运行时安全实践","slug":"_4-运行时安全实践","link":"#_4-运行时安全实践","children":[{"level":3,"title":"4.1 最小权限运行","slug":"_4-1-最小权限运行","link":"#_4-1-最小权限运行","children":[]},{"level":3,"title":"4.2 端口与网络控制","slug":"_4-2-端口与网络控制","link":"#_4-2-端口与网络控制","children":[]},{"level":3,"title":"4.3 凭证管理","slug":"_4-3-凭证管理","link":"#_4-3-凭证管理","children":[]}]},{"level":2,"title":"5. 持续安全治理","slug":"_5-持续安全治理","link":"#_5-持续安全治理","children":[]},{"level":2,"title":"6. 常见误区","slug":"_6-常见误区","link":"#_6-常见误区","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"docker/19-Docker安全全景扫描-Rootless模式与镜像漏洞检测实战.md","filePath":"docker/19-Docker安全全景扫描-Rootless模式与镜像漏洞检测实战.md"}'),t={name:"docker/19-Docker安全全景扫描-Rootless模式与镜像漏洞检测实战.md"};function r(o,l,h,n,d,c){return e(),a("div",null,[...l[0]||(l[0]=[s('<h1 id="_19-docker安全全景扫描-rootless模式与镜像漏洞检测实战" tabindex="-1">19-Docker安全全景扫描-Rootless模式与镜像漏洞检测实战 <a class="header-anchor" href="#_19-docker安全全景扫描-rootless模式与镜像漏洞检测实战" aria-label="Permalink to “19-Docker安全全景扫描-Rootless模式与镜像漏洞检测实战”">​</a></h1><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to “引言”">​</a></h2><p>容器安全不是“把程序装进容器就安全”。它需要覆盖镜像构建、运行时权限、漏洞扫描和持续治理。</p><p>本篇文章从 Rootless 模式、镜像扫描、运行权限和安全实践四个维度，帮助你构建更稳妥的 Docker 安全体系。</p><h2 id="_1-容器并非天然安全" tabindex="-1">1. 容器并非天然安全 <a class="header-anchor" href="#_1-容器并非天然安全" aria-label="Permalink to “1. 容器并非天然安全”">​</a></h2><p>容器提供隔离，但它仍共享宿主机内核。如果镜像中含有漏洞，或容器以 root 权限运行，就存在被攻击后破坏宿主机的风险。</p><p>安全风险常见于：</p><ul><li>未审核的基础镜像；</li><li>过度开放权限；</li><li>暴露无关端口；</li><li>运行时凭证泄露；</li><li>不定期更新依赖。</li></ul><h2 id="_2-rootless-模式-降低特权风险" tabindex="-1">2. Rootless 模式：降低特权风险 <a class="header-anchor" href="#_2-rootless-模式-降低特权风险" aria-label="Permalink to “2. Rootless 模式：降低特权风险”">​</a></h2><p>Rootless 模式让 Docker 守护进程和容器尽量以非 root 用户运行。</p><p>优点：</p><ul><li>减少提权攻击面；</li><li>降低容器突破后的危害；</li><li>更符合最小权限原则。</li></ul><p>配置示例（Linux）：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dockerd-rootless.sh</span></span></code></pre></div><p>在生产环境，优先让容器内部进程使用非 root 用户：</p><div class="language-dockerfile"><button title="Copy Code" class="copy"></button><span class="lang">dockerfile</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">USER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> node</span></span></code></pre></div><h2 id="_3-镜像漏洞扫描" tabindex="-1">3. 镜像漏洞扫描 <a class="header-anchor" href="#_3-镜像漏洞扫描" aria-label="Permalink to “3. 镜像漏洞扫描”">​</a></h2><p>镜像往往是安全链条的起点。常见扫描工具包括：</p><ul><li>Docker Hub 安全扫描；</li><li>Trivy；</li><li>Clair；</li><li>Anchore；</li><li>Aqua。</li></ul><p>扫描内容包括：</p><ul><li>基础镜像漏洞；</li><li>应用依赖漏洞；</li><li>公开端口与运行命令；</li><li>证书与凭证泄露。</li></ul><p>示例：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">trivy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp:latest</span></span></code></pre></div><h2 id="_4-运行时安全实践" tabindex="-1">4. 运行时安全实践 <a class="header-anchor" href="#_4-运行时安全实践" aria-label="Permalink to “4. 运行时安全实践”">​</a></h2><h3 id="_4-1-最小权限运行" tabindex="-1">4.1 最小权限运行 <a class="header-anchor" href="#_4-1-最小权限运行" aria-label="Permalink to “4.1 最小权限运行”">​</a></h3><ul><li>使用 <code>USER</code> 设定非 root 用户；</li><li>不要在容器内安装调试工具；</li><li>使用 <code>--read-only</code> 让根文件系统只读；</li><li>对必要目录使用 <code>tmpfs</code> 或只读挂载。</li></ul><h3 id="_4-2-端口与网络控制" tabindex="-1">4.2 端口与网络控制 <a class="header-anchor" href="#_4-2-端口与网络控制" aria-label="Permalink to “4.2 端口与网络控制”">​</a></h3><ul><li>只暴露必要端口；</li><li>使用防火墙和网络策略；</li><li>不要把容器直接曝露在公网上。</li></ul><h3 id="_4-3-凭证管理" tabindex="-1">4.3 凭证管理 <a class="header-anchor" href="#_4-3-凭证管理" aria-label="Permalink to “4.3 凭证管理”">​</a></h3><ul><li>不要把密钥写入 Dockerfile；</li><li>使用 <code>docker secret</code>、环境变量或配置中心；</li><li>定期轮换凭证。</li></ul><h2 id="_5-持续安全治理" tabindex="-1">5. 持续安全治理 <a class="header-anchor" href="#_5-持续安全治理" aria-label="Permalink to “5. 持续安全治理”">​</a></h2><p>安全不是一次性任务，而是持续过程。</p><p>建议做法：</p><ul><li>把镜像扫描作为 CI 阶段；</li><li>定期更新基础镜像和依赖；</li><li>监控异常行为；</li><li>建立安全事件响应流程。</li></ul><h2 id="_6-常见误区" tabindex="-1">6. 常见误区 <a class="header-anchor" href="#_6-常见误区" aria-label="Permalink to “6. 常见误区”">​</a></h2><ul><li>认为容器隔离等于安全隔离；</li><li>只关注应用代码漏洞，不关注基础镜像漏洞；</li><li>觉得 Rootless 复杂就不做；</li><li>认为扫描一次就够。安全需要持续关注。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>Docker 安全要从“镜像安全”“运行时权限”“漏洞扫描”“持续治理”四个层面构建。Rootless 模式和镜像扫描是两个重要切入点，但最终的安全能力来自于“把安全纳入交付流程”，而不是偶尔做一次检查。</p>',38)])])}const _=i(t,[["render",r]]);export{p as __pageData,_ as default};
